%[text] # cuDSS: CPU/GPU sparse-solver comparison
%[text] This example compares the two NVIDIA cuDSS matrix modes with OpenSees' native sparse CPU solvers. Every solver receives the same elastic plane-stress model, constraints, ordering, loading, and number of analysis steps.
%[text] Model construction, one-time GPU startup, the first `analyze(1)` call, and repeated calls are reported separately. The measured crossover belongs to the computer used for the test; it is not a universal solver threshold.
clear;
clc;
close all;
outputFolder = fullfile("figures");
if ~isfolder(outputFolder)
    mkdir(outputFolder);
end
%%
%[text] ### 1. Choose the matrix type before the solver
%[text] `CuDSSGeneral` accepts a general sparse tangent matrix, while `CuDSSSPD` requires a symmetric positive-definite matrix. `UmfPack` remains the common timing and accuracy reference. `SuperLU` and `SparseSPD` provide the built-in OpenSees sparse CPU comparisons.
%[text] The panel used here is elastic, stable, and fully constrained, so all listed matrix assumptions are valid.

SolverGuide = table( ...
    ["CuDSSGeneral"; "CuDSSSPD"; "UmfPack"; "SuperLU"; "SparseSPD"], ...
    ["GPU"; "GPU"; "CPU"; "CPU"; "CPU"], ...
    ["general"; "symmetric positive definite"; "general"; "general"; ...
     "symmetric positive definite"], ...
    repmat("UmfPack",5,1), ...
    'VariableNames',{'Command','Backend','MatrixAssumption','TimingReference'});
disp(SolverGuide); %[output:75e77166]
%%
%[text] ### 2. Configure the runtime and benchmark
%[text] Leave both paths empty to use automatic runtime discovery. If discovery fails, enter the CUDA and cuDSS installation roots or DLL directories. CUDA and cuDSS must target the same CUDA major version. CPU cases remain available without an NVIDIA GPU.

cudaPath = "";
cudssPath = "";
% cudaPath = "C:\Program Files\NVIDIA GPU Computing Toolkit\CUDA\v12.6";
% cudssPath = "C:\Program Files\NVIDIA cuDSS\v0.8";

CuDSSOptions = buildCuDSSOptions(cudaPath,cudssPath);

% Every solver is measured through one million active equations.
TargetDOFs = [100 500 1000 2000 5000 10000 20000 50000 100000 1000000];

% Keep the two cuDSS variants together in tables, plots, and legends.
Solvers = ["CuDSSGeneral" "CuDSSSPD" "UmfPack" "SuperLU" "SparseSPD"];
NumberOfLoadSteps = 4;

opsMat = OpenSeesMatlab();
ops = opsMat.opensees;
%%
%[text] ### 3. Measure one-time GPU startup separately
%[text] The first cuDSS use in a MATLAB process loads the runtime, creates a CUDA context, and selects a device. The smoke case records this one-time cost. `-verbose` is used only here and is removed from the benchmark timings.

CuDSSAvailable = true;
CuDSSStartupCaseSeconds = NaN;
CuDSSFailureMessage = "";
try %[output:group:09e56f3e]
    startupTimer = tic;
    runPlaneCase(ops,500,"CuDSSGeneral",1,[CuDSSOptions {"-verbose"}]); %[output:7346b01e]
    CuDSSStartupCaseSeconds = toc(startupTimer);
    fprintf("cuDSS startup plus 500-equation smoke case: %.3f s\n", ... %[output:46f96966]
        CuDSSStartupCaseSeconds); %[output:46f96966]
catch exception
    CuDSSAvailable = false;
    CuDSSFailureMessage = string(exception.message);
    warning("cuDSS is unavailable; CPU cases will continue.\n%s", ...
        CuDSSFailureMessage);
end %[output:group:09e56f3e]
%%
%[text] ### 4. Run the same model with every solver
%[text] `ModelBuildSeconds` includes domain construction only. `FirstAnalyzeSeconds` is the first `analyze(1)` call for a newly created system. `RepeatedAnalyzeSeconds` is the median of the remaining calls. Because the tangent is unchanged in this linear example, repeated cuDSS calls demonstrate the extension's normal factorization-reuse behavior.
%[text] Add `"-noReuseFactorization"` to `CuDSSOptions` only when the purpose is to measure raw refactorization rather than normal application performance.

numberOfCases = numel(TargetDOFs)*numel(Solvers);
records = repmat(emptyResult(),numberOfCases,1);
recordIndex = 0;

for targetDOF = TargetDOFs %[output:group:20d7d408]
    for solver = Solvers
        recordIndex = recordIndex + 1;

        if startsWith(solver,"CuDSS") && ~CuDSSAvailable
            records(recordIndex) = failedResult(targetDOF,solver, ...
                "cuDSS runtime unavailable: " + CuDSSFailureMessage);
            continue;
        end

        fprintf("Running %-14s at a target of %d equations...\n",solver,targetDOF); %[output:11e7f01b]
        try
            records(recordIndex) = runPlaneCase(ops,targetDOF,solver, ...
                NumberOfLoadSteps,CuDSSOptions);
        catch exception
            records(recordIndex) = failedResult(targetDOF,solver, ...
                string(exception.message));
        end
    end
end %[output:group:20d7d408]

Results = struct2table(records);
Results = addPairwiseComparisons(Results);
%%
%[text] ### 5. Check numerical agreement first
%[text] All solvers use `UmfPack` as one common reference, matching the convention used in the publication figures. A speedup greater than one means that the selected solver was faster than `UmfPack` for the measured phase.

ResultSummary = Results(:,{ ...
    'TargetDOF','ActualDOF','Solver','ReferenceSolver','Status', ...
    'FirstAnalyzeSeconds','RepeatedAnalyzeSeconds', ...
    'FirstSpeedup','RepeatedSpeedup','RelativeTipError'});
disp(ResultSummary); %[output:4e1af09e]

IncompleteCases = Results(Results.Status ~= "ok", ...
    {'TargetDOF','Solver','Status','Message'});
if ~isempty(IncompleteCases)
    disp("Cases that were not completed:");
    disp(IncompleteCases);
end
%%
%[text] ### 6. Publication-style solution-time figure
%[text] This follows the original manuscript layout: first and repeated solutions are shown side by side, the equation count is logarithmic, and solution time remains linear. The large canvas and common legend preserve readable type and markers when the figure is reduced to journal width.

fontName = "Times New Roman";
fontSize = 17;
lineWidth = 2;
markerSize = 9;
axisLineWidth = 1;
PlotStyle = solverPlotStyle(Solvers);

figTime = figure( ... %[output:09959fff]
    "Name","Sparse-solver solution time", ... %[output:09959fff]
    "Color","w", ... %[output:09959fff]
    "Units","pixels", ... %[output:09959fff]
    "Position",[60 80 1200 500]); %[output:09959fff]
timeLayout = tiledlayout(figTime,1,2, ... %[output:09959fff]
    "TileSpacing","compact","Padding","compact"); %[output:09959fff]

axFirst = nexttile(timeLayout); %[output:09959fff]
plotSolverMetric(axFirst,Results,Solvers,"FirstAnalyzeSeconds", ... %[output:09959fff]
    PlotStyle,lineWidth,markerSize,false); %[output:09959fff]
setPublicationAxes(axFirst,fontName,fontSize,axisLineWidth); %[output:09959fff]
title(axFirst,"(a) First solution of each system","FontWeight","normal"); %[output:09959fff]
ylabel(axFirst,"Solution time (s)"); %[output:09959fff]
ylim(axFirst, [1e-4 1e2]); %[output:09959fff]


axRepeated = nexttile(timeLayout); %[output:09959fff]
plotSolverMetric(axRepeated,Results,Solvers,"RepeatedAnalyzeSeconds", ... %[output:09959fff]
    PlotStyle,lineWidth,markerSize,false); %[output:09959fff]
setPublicationAxes(axRepeated,fontName,fontSize,axisLineWidth); %[output:09959fff]
title(axRepeated,"(b) Repeated tangent solution","FontWeight","normal"); %[output:09959fff]
ylabel(axRepeated,"Median solution time (s)"); %[output:09959fff]
ylim(axRepeated, [1e-4 1e2]); %[output:09959fff]


timeLegend = legend(axRepeated,"Location","northwest", ... %[output:09959fff]
    "NumColumns",1,"Box","on","Color","white", ... %[output:09959fff]
    "EdgeColor",[0.35 0.35 0.35],"FontName",fontName, ... %[output:09959fff]
    "FontSize",fontSize-1); %[output:09959fff]
% timeLegend.Layout.Tile = "south";

set(axFirst,"YScale","log"); %[output:09959fff]
set(axRepeated,"YScale","log"); %[output:09959fff]
drawnow;

% Vector export for a manuscript:
exportgraphics(figTime,fullfile(outputFolder,"CUDSSSolverTime.pdf"), ... %[output:group:57394e5b] %[output:09959fff]
    "ContentType","vector"); %[output:group:57394e5b] %[output:09959fff]
timeFigureData = Results(:, { ...
    'ActualDOF','Solver','FirstAnalyzeSeconds','RepeatedAnalyzeSeconds'});
writetable(timeFigureData, fullfile(outputFolder, "CUDSSSolverTime.csv"));
%%
%[text] ### 7. Accuracy and speedup overview
%[text] The two related comparisons share one large, horizontally arranged figure. The left panel measures displacement agreement with `UmfPack`; the right panel shows repeated-solution speedup relative to the same reference. Exact zero error is replaced by `eps` only on the logarithmic display axis; the results table retains zero.

figComparison = figure( ... %[output:0414a251]
    "Name","Sparse-solver accuracy and speedup", ... %[output:0414a251]
    "Color","w", ... %[output:0414a251]
    "Units","pixels", ... %[output:0414a251]
    "Position",[80 90 1200 500]); %[output:0414a251]
comparisonLayout = tiledlayout(figComparison,1,2, ... %[output:0414a251]
    "TileSpacing","compact","Padding","compact"); %[output:0414a251]

axError = nexttile(comparisonLayout); %[output:0414a251]
plotComparisonMetric(axError,Results,Solvers,"RelativeTipError", ... %[output:0414a251]
    PlotStyle,lineWidth,markerSize,true); %[output:0414a251]
setPublicationAxes(axError,fontName,fontSize,axisLineWidth); %[output:0414a251]
title(axError,"(a) Displacement accuracy","FontWeight","normal"); %[output:0414a251]
ylabel(axError,"Relative displacement error"); %[output:0414a251]

axSpeedup = nexttile(comparisonLayout); %[output:0414a251]
plotComparisonMetric(axSpeedup,Results,Solvers,"RepeatedSpeedup", ... %[output:0414a251]
    PlotStyle,lineWidth,markerSize,false); %[output:0414a251]
yline(axSpeedup,1,"--","UmfPack reference", ... %[output:0414a251]
    "Color",[0.25 0.25 0.25],"LineWidth",1.0, ... %[output:0414a251]
    "FontSize",fontSize-1, ... %[output:0414a251]
    "LabelHorizontalAlignment","right","HandleVisibility","off"); %[output:0414a251]
setPublicationAxes(axSpeedup,fontName,fontSize,axisLineWidth); %[output:0414a251]
title(axSpeedup,"(b) Repeated-solution speedup","FontWeight","normal"); %[output:0414a251]
ylabel(axSpeedup,"Speedup"); %[output:0414a251]

comparisonLegend = legend(axError,"Location","northwest", ... %[output:0414a251]
    "NumColumns",1,"Box","on","Color","white", ... %[output:0414a251]
    "EdgeColor",[0.35 0.35 0.35],"FontName",fontName, ... %[output:0414a251]
    "FontSize",fontSize-1); %[output:0414a251]
% comparisonLegend.Layout.Tile = "south";
drawnow;

% Vector export for a manuscript:
exportgraphics(figComparison, ... %[output:group:2ec671d1] %[output:0414a251]
    fullfile(outputFolder,"CUDSSSolverAccuracyAndSpeedup.pdf"), ... %[output:0414a251]
    "ContentType","vector"); %[output:group:2ec671d1] %[output:0414a251]
comparisonFigureData = Results(:, { ...
    'ActualDOF','Solver','RelativeTipError','RepeatedSpeedup'});
writetable(comparisonFigureData, ...
    fullfile(outputFolder, "CUDSSSolverAccuracyAndSpeedup.csv"));
%%
%[text] ### 8. Interpret the result
%[text] Confirm displacement agreement before using any timing result. Then distinguish the first solution from repeated solutions: GPU initialization, matrix analysis, factorization, transfer, and reuse affect the two measurements differently.
%[text] For a nonlinear production model, repeat this comparison with the same convergence test, algorithm, load history, and recorders. Start with `CuDSSGeneral`; select `CuDSSSPD` only when every tangent matrix is guaranteed to remain symmetric positive definite.

%% Local functions
function result = runPlaneCase(ops,targetDOF,solver,numberOfSteps,cudssOptions)
    [nx,ny,actualDOF] = balancedMesh(targetDOF);
    cleanup = onCleanup(@() ops.wipe());

    modelTimer = tic;
    ops.wipe();
    ops.model("basic","-ndm",2,"-ndf",2);
    ops.nDMaterial("ElasticIsotropic",1,2.0e11,0.30,7850.0);
    ops.block2D(nx,ny,1,1,"quad",0.10,"PlaneStress",1, ...
        1,0,0, 2,10,0, 3,10,10, 4,0,10);
    ops.fixX(0.0,1,1);
    ops.timeSeries("Linear",1);
    ops.pattern("Plain",1,1);

    rightEdgeTags = (0:ny)*(nx+1)+nx+1;
    verticalLoad = -1.0e6/numel(rightEdgeTags);
    for nodeTag = rightEdgeTags
        ops.load(nodeTag,0.0,verticalLoad);
    end
    modelBuildSeconds = toc(modelTimer);

    ops.constraints("Plain");
    ops.numberer("RCM");
    selectSystem(ops,solver,cudssOptions);
    ops.integrator("LoadControl",1/numberOfSteps);
    ops.algorithm("Linear");
    ops.analysis("Static");

    analyzeSeconds = zeros(1,numberOfSteps);
    for step = 1:numberOfSteps
        solveTimer = tic;
        returnCode = ops.analyze(1);
        analyzeSeconds(step) = toc(solveTimer);
        if returnCode ~= 0
            error("CuDSSExample:AnalyzeFailed", ...
                "analyze(1) returned %d at load step %d.",returnCode,step);
        end
    end

    middleRightTag = floor(ny/2)*(nx+1)+nx+1;
    tipDisplacement = ops.nodeDisp(middleRightTag);

    result = emptyResult();
    result.TargetDOF = targetDOF;
    result.ActualDOF = actualDOF;
    result.Nx = nx;
    result.Ny = ny;
    result.Solver = solver;
    result.Family = solverFamily(solver);
    result.ReferenceSolver = referenceSolver(solver);
    result.Status = "ok";
    result.ModelBuildSeconds = modelBuildSeconds;
    result.FirstAnalyzeSeconds = analyzeSeconds(1);
    if numberOfSteps > 1
        result.RepeatedAnalyzeSeconds = median(analyzeSeconds(2:end));
    end
    result.TotalAnalyzeSeconds = sum(analyzeSeconds);
    result.TipUx = tipDisplacement(1);
    result.TipUy = tipDisplacement(2);
end

function selectSystem(ops,solver,cudssOptions)
    switch solver
        case "CuDSSGeneral"
            ops.system("CuDSSGeneral",cudssOptions{:});
        case "CuDSSSPD"
            ops.system("CuDSSSPD",cudssOptions{:});
        case "UmfPack"
            ops.system("UmfPack");
        case "SuperLU"
            ops.system("SuperLU");
        case "SparseSPD"
            ops.system("SparseSPD");
        otherwise
            error("CuDSSExample:UnknownSolver","Unknown solver: %s",solver);
    end
end

function options = buildCuDSSOptions(cudaPath,cudssPath)
    options = {};
    if strlength(cudaPath) > 0
        options = [options {"-cudaPath",cudaPath}];
    end
    if strlength(cudssPath) > 0
        options = [options {"-cudssPath",cudssPath}];
    end
end

function results = addPairwiseComparisons(results)
    for rowIndex = 1:height(results)
        if results.Status(rowIndex) ~= "ok"
            continue;
        end

        referenceRows = results.TargetDOF == results.TargetDOF(rowIndex) & ...
            results.Solver == results.ReferenceSolver(rowIndex) & ...
            results.Status == "ok";
        if ~any(referenceRows)
            continue;
        end

        referenceRow = find(referenceRows,1);
        referenceMagnitude = hypot(results.TipUx(referenceRow), ...
            results.TipUy(referenceRow));
        results.RelativeTipError(rowIndex) = hypot( ...
            results.TipUx(rowIndex)-results.TipUx(referenceRow), ...
            results.TipUy(rowIndex)-results.TipUy(referenceRow)) / ...
            max(referenceMagnitude,eps);
        results.FirstSpeedup(rowIndex) = ...
            results.FirstAnalyzeSeconds(referenceRow) / ...
            results.FirstAnalyzeSeconds(rowIndex);
        results.RepeatedSpeedup(rowIndex) = ...
            results.RepeatedAnalyzeSeconds(referenceRow) / ...
            results.RepeatedAnalyzeSeconds(rowIndex);
    end
end

function style = solverPlotStyle(solvers)
    knownSolvers = ["CuDSSGeneral" "CuDSSSPD" ...
        "UmfPack" "SuperLU" "SparseSPD"];
    colors = [ ...
        0.000 0.318 0.620
        0.443 0.204 0.678
        0.902 0.380 0.000
        0.450 0.450 0.450
        0.450 0.450 0.450];
    markers = ["o" "s" "d" "^" "v"];
    lineStyles = ["-" "-" "--" "-." ":"];

    [found,locations] = ismember(solvers,knownSolvers);
    if ~all(found)
        error("CuDSSExample:MissingPlotStyle", ...
            "A plot style is not defined for: %s",strjoin(solvers(~found),", "));
    end

    style = table(colors(locations,:),markers(locations)',lineStyles(locations)', ...
        'VariableNames',{'Color','Marker','LineStyle'});
end

function plotSolverMetric(ax,results,solvers,metric,style, ...
        lineWidth,markerSize,useLogY)
    hold(ax,"on");
    values = results.(metric);
    for solverIndex = 1:numel(solvers)
        solver = solvers(solverIndex);
        rows = results.Solver == solver & results.Status == "ok";
        data = sortrows(table(results.ActualDOF(rows),values(rows), ...
            'VariableNames',{'DOF','Value'}),'DOF');
        valid = isfinite(data.DOF) & isfinite(data.Value) & ...
            data.DOF > 0 & data.Value > 0;
        plot(ax,data.DOF(valid),data.Value(valid), ...
            "LineStyle",style.LineStyle(solverIndex), ...
            "Color",style.Color(solverIndex,:), ...
            "Marker",style.Marker(solverIndex), ...
            "MarkerSize",markerSize,"MarkerFaceColor","w", ...
            "LineWidth",lineWidth,"DisplayName",solver);
    end
    set(ax,"XScale","log");
    if useLogY
        set(ax,"YScale","log");
    else
        set(ax,"YScale","linear");
        ylim(ax,[0 max(ylim(ax))*1.03]);
    end
    xlabel(ax,"Number of active equations");
end

function plotComparisonMetric(ax,results,solvers,metric,style, ...
        lineWidth,markerSize,useLogY)
    hold(ax,"on");
    values = results.(metric);
    for solverIndex = 1:numel(solvers)
        solver = solvers(solverIndex);
        rows = results.Solver == solver & results.Status == "ok";
        plotValues = values(rows);
        if useLogY
            plotValues = max(abs(plotValues),eps);
        end
        data = sortrows(table(results.ActualDOF(rows),plotValues, ...
            'VariableNames',{'DOF','Value'}),'DOF');
        valid = isfinite(data.DOF) & isfinite(data.Value) & ...
            data.DOF > 0 & data.Value > 0;
        plot(ax,data.DOF(valid),data.Value(valid), ...
            "LineStyle",style.LineStyle(solverIndex), ...
            "Color",style.Color(solverIndex,:), ...
            "Marker",style.Marker(solverIndex), ...
            "MarkerSize",markerSize,"MarkerFaceColor","w", ...
            "LineWidth",lineWidth,"DisplayName",solver);
    end
    set(ax,"XScale","log");
    if useLogY
        set(ax,"YScale","log");
    end
    xlabel(ax,"Number of active equations");
end

function setPublicationAxes(ax,fontName,fontSize,axisLineWidth)
    box(ax,"on");
    grid(ax,"on");
    ax.XMinorGrid = "off";
    ax.YMinorGrid = "off";
    ax.GridAlpha = 0.16;
    ax.GridLineStyle = "-";
    set(ax, ...
        "FontName",fontName, ...
        "FontSize",fontSize, ...
        "LineWidth",axisLineWidth, ...
        "TickDir","in", ...
        "TickLength",[0.012 0.012], ...
        "XMinorTick","on", ...
        "YMinorTick","on", ...
        "Layer","top");
    ax.XLabel.FontName = fontName;
    ax.YLabel.FontName = fontName;
    ax.Title.FontName = fontName;
    ax.XLabel.FontSize = fontSize+1;
    ax.YLabel.FontSize = fontSize+1;
    ax.Title.FontSize = fontSize+1;
end

function family = solverFamily(solver)
    if ismember(solver,["CuDSSSPD" "SparseSPD"])
        family = "SPD";
    else
        family = "general";
    end
end

function reference = referenceSolver(~)
    reference = "UmfPack";
end

function result = failedResult(targetDOF,solver,message)
    result = statusResult(targetDOF,solver,"failed",message);
end

function result = statusResult(targetDOF,solver,status,message)
    result = emptyResult();
    result.TargetDOF = targetDOF;
    result.Solver = solver;
    result.Family = solverFamily(solver);
    result.ReferenceSolver = referenceSolver(solver);
    result.Status = status;
    result.Message = string(message);
end

function result = emptyResult()
    result = struct( ...
        'TargetDOF',NaN, ...
        'ActualDOF',NaN, ...
        'Nx',NaN, ...
        'Ny',NaN, ...
        'Solver',"", ...
        'Family',"", ...
        'ReferenceSolver',"", ...
        'Status',"", ...
        'ModelBuildSeconds',NaN, ...
        'FirstAnalyzeSeconds',NaN, ...
        'RepeatedAnalyzeSeconds',NaN, ...
        'TotalAnalyzeSeconds',NaN, ...
        'TipUx',NaN, ...
        'TipUy',NaN, ...
        'FirstSpeedup',NaN, ...
        'RepeatedSpeedup',NaN, ...
        'RelativeTipError',NaN, ...
        'Message',"");
end

function [nx,ny,actualDOF] = balancedMesh(targetDOF)
    center = max(1,round(sqrt(targetDOF/2)));
    best = [Inf Inf 1 1];
    for nxCandidate = max(1,center-20):center+20
        estimatedNy = max(1,round(targetDOF/(2*nxCandidate)-1));
        for nyCandidate = max(1,estimatedNy-1):estimatedNy+1
            candidateDOF = 2*nxCandidate*(nyCandidate+1);
            score = [abs(candidateDOF-targetDOF), ...
                abs(nxCandidate-nyCandidate),nxCandidate,nyCandidate];
            changedIndex = find(score ~= best,1);
            if ~isempty(changedIndex) && score(changedIndex) < best(changedIndex)
                best = score;
            end
        end
    end
    nx = best(3);
    ny = best(4);
    actualDOF = 2*nx*(ny+1);
end

